static void process_ingress(struct dppd_worker *worker, const struct dppd_port *ingress)
{
    if (worker_io_quiesced(worker) || atomic_load_explicit(&ingress->removed, memory_order_acquire))
        return;
    struct rte_mbuf *packets[DPPD_MAX_BURST];
    /** 最多接收 burst_size 个包，不等待凑满 */
    uint16_t count = rte_eth_rx_burst(ingress->port_id, worker->queue_id, packets, worker->runtime->config.burst_size);
    process_batch(worker, ingress, packets, count, false, 0);
}

static void process_batch(struct dppd_worker *worker, const struct dppd_port *ingress, struct rte_mbuf **rx,
    uint16_t received, bool retry, uint64_t expires)
{
    struct dppd_runtime *runtime = worker->runtime;
    /** 按出口暂存待发送的 mbuf 指针、长度和数量，逐包处理结束后统一批量发送 */
    struct rte_mbuf *tx[DPPD_MAX_PORTS][DPPD_MAX_BURST];
    uint32_t tx_lengths[DPPD_MAX_PORTS][DPPD_MAX_BURST];
    uint16_t counts[DPPD_MAX_PORTS] = {0};
    struct dppd_stats_values delta = {0}, outputs[DPPD_MAX_PORTS] = {0};
    struct dppd_software_count_batch rule_counts = {0};
    if (worker_io_quiesced(worker)) {
        /** RX 返回的报文已归线程所有，事件不能让这批 mbuf 因提前返回而泄漏 */
        free_packets(rx, received);
        return;
    }
    if (received == 0)
        return;
    delta.rx_packets = retry ? 0 : received;
    const struct dppd_port *paired =
        runtime->ipv4_router == NULL ? dppd_devices_find(&runtime->devices, ingress->peer_port_id) : NULL;
    for (uint16_t i = 0; i < received; ++i) {
        /** packet 保存解析字段，decision 保存处理决定，rx[i] 指向原始报文 */
        struct dppd_pipeline_decision decision;
        struct dppd_packet packet = {0};
        uint32_t length = rte_pktmbuf_pkt_len(rx[i]);
        if (!retry)
            delta.rx_bytes += length;
        /** 逐包进入 packet_mbuf.c 提取报文头字段，burst 只批量收发，不省略逐包解析 */
        int parsed = dppd_packet_parse_mbuf(rx[i], &packet);
        packet.neighbor_retry = retry;
        /** 隧道统计是外层中转观察，既不替换 ACL 字段，也不因内层错误改变已有放行结果 */
        if (!retry) {
            delta.tunnel_vxlan_packets += packet.tunnel.type == DPPD_TUNNEL_VXLAN;
            delta.tunnel_geneve_packets += packet.tunnel.type == DPPD_TUNNEL_GENEVE;
            delta.tunnel_gre_packets += packet.tunnel.type == DPPD_TUNNEL_GRE;
            delta.tunnel_malformed += packet.tunnel.status == DPPD_PARSE_MALFORMED;
            delta.tunnel_unsupported += packet.tunnel.status == DPPD_PARSE_UNSUPPORTED;
        }
        if (parsed == DPPD_PARSE_MALFORMED)
            delta.rx_malformed++;
        else if (parsed == DPPD_PARSE_UNSUPPORTED)
            delta.rx_unsupported++;
        if (runtime->nd6 != NULL && parsed != DPPD_PARSE_MALFORMED &&
            dppd_nd6_input(runtime->nd6, ingress->port_id, rx[i], &packet, dppd_monotonic_ms(), send_nd6, worker)) {
            delta.nd6_rx_packets++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        if (packet.l3_type == DPPD_L3_IPV6 && !dppd_nd6_port_ready(runtime->nd6, ingress->port_id)) {
            delta.nd6_not_ready_drops++;
            delta.policy_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 未启用连接跟踪
         *   → routed_decide → decision
         *
         * 启用连接跟踪
         *   → stateful_decide
         *       校验、准备候选会话
         *         → routed_decide
         *         → 检查出口、改写实际报文
         *         → 成功提交会话，失败取消候选
         */
        if (runtime->conntrack != NULL)
            stateful_decide(worker, ingress, &rx[i], parsed, &packet, &decision, &rule_counts);
        else
            routed_decide(runtime, ingress->port_id, parsed, &packet, &decision, &rule_counts);

        /**
         * ND_PENDING 表示下一跳 MAC 尚未取得，先尝试把当前 mbuf 交给 ND 等待队列
         * 入队成功 → 队列接管 mbuf，continue 处理下一个包，此处不能释放或发送它
         * 入队失败 → mbuf 仍归当前线程，继续下面的丢弃分支并释放
         */
        if (decision.drop_reason == DPPD_DROP_ND_PENDING) {
            struct dppd_nd6_pending pending = {.mbuf = rx[i],
                .ingress = ingress->port_id,
                .queue = worker->queue_id,
                .expires_ms = expires};
            if (dppd_nd6_hold(runtime->nd6, decision.ipv4.port_id, decision.ipv4.next_hop6, pending,
                    dppd_monotonic_ms()) == 0) {
                delta.nd6_queued++;
                continue;
            }
            delta.nd6_queue_drops++;
        }
        /**
         * 决定函数只填写结果，worker 在这里执行丢弃并按原因更新统计
         * 释放当前报文后继续处理本批下一个包，不影响其他报文
         */
        if (decision.action != DPPD_PACKET_FORWARD) {
            if (decision.drop_reason != DPPD_DROP_MALFORMED)
                delta.policy_drops++;
            if (decision.drop_reason == DPPD_DROP_ND_NOT_READY)
                delta.nd6_not_ready_drops++;
            else if (decision.drop_reason == DPPD_DROP_POLICY)
                delta.rule_drops++;
            else if (decision.drop_reason == DPPD_DROP_NO_ROUTE)
                delta.no_route_drops++;
            else if (decision.drop_reason == DPPD_DROP_NO_NEIGHBOR)
                delta.no_neighbor_drops++;
            else if (decision.drop_reason == DPPD_DROP_IPV4_UNSUPPORTED)
                delta.ipv4_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_IPV6_UNSUPPORTED)
                delta.ipv6_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_INVALID)
                delta.ct_invalid_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_FULL)
                delta.ct_full_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_UNSUPPORTED)
                delta.ct_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_ZONE)
                delta.ct_zone_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_CHECKSUM)
                delta.ct_checksum_drops++;
            else if (decision.drop_reason == DPPD_DROP_NAT_POOL)
                delta.nat_pool_drops++;
            else if (decision.drop_reason == DPPD_DROP_NAT_MISS)
                delta.nat_miss_drops++;
            else if (decision.drop_reason == DPPD_DROP_TTL) {
                if (packet.l3_type == DPPD_L3_IPV6)
                    delta.ipv6_hop_drops++;
                else
                    delta.ipv4_ttl_drops++;
            } else if (decision.drop_reason == DPPD_DROP_REWRITE) {
                if (packet.l3_type == DPPD_L3_IPV6)
                    delta.ipv6_rewrite_drops++;
                else
                    delta.ipv4_rewrite_drops++;
            } else if (decision.drop_reason == DPPD_DROP_EGRESS)
                delta.egress_drops++;
            /** 归还当前 mbuf，再进入逐包循环的下一轮 */
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 根据处理决定取得实际出口对象，三层模式按出口编号查找，端口配对模式复用 paired
         * FORWARD 只表示策略允许，发送前仍须确认出口存在、编号一致且可发送
         */
        const struct dppd_port *egress =
            runtime->ipv4_router != NULL ? dppd_devices_find(&runtime->devices, decision.egress_port) : paired;
        if (egress == NULL || egress->port_id != decision.egress_port || !dppd_port_tx_available(egress)) {
            delta.policy_drops++;
            delta.egress_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 三层转发在这里改写报文头，启用连接跟踪时已由 stateful_decide 改写，不能再次递减跳数
         * IPv6 普通转发：目的 MAC 改为下一跳 MAC，源 MAC 改为出口 MAC，Hop Limit 减 1
         *
         * &rx[i] 允许改写函数在需要复制报文时替换 mbuf 指针，后续发送使用替换后的指针
         * &packet 提供已解析的头部信息，decision.ipv4 是 IPv4/IPv6 共用的转发结果
         * 改写失败则释放当前包；成功后继续加入出口发送批次，此处尚未交给网卡
         */
        if (decision.routed && runtime->conntrack == NULL) {
            bool ipv6 = packet.l3_type == DPPD_L3_IPV6;
            int rc = ipv6 ? dppd_ipv6_rewrite(&rx[i], &packet, &decision.ipv4, egress->mac.addr_bytes)
                          : dppd_ipv4_rewrite(&rx[i], &packet, &decision.ipv4, egress->mac.addr_bytes);
            if (rc != 0) {
                delta.policy_drops++;
                if (ipv6) {
                    if (rc == -ETIMEDOUT)
                        delta.ipv6_hop_drops++;
                    else if (rc == -EBADMSG)
                        delta.ipv6_checksum_drops++;
                    else if (rc == -ENOTSUP)
                        delta.ipv6_unsupported_drops++;
                    else
                        delta.ipv6_rewrite_drops++;
                } else if (rc == -ETIMEDOUT)
                    delta.ipv4_ttl_drops++;
                else if (rc == -EBADMSG)
                    delta.ipv4_checksum_drops++;
                else if (rc == -ENOTSUP)
                    delta.ipv4_unsupported_drops++;
                else
                    delta.ipv4_rewrite_drops++;
                rte_pktmbuf_free(rx[i]);
                continue;
            }
        }
        /** 将规则 MARK 写入 mbuf 的附加信息并设置有效标志，不向报文字节中插入标记 */
        if (decision.has_mark) {
            rx[i]->hash.fdir.hi = decision.mark_id;
            rx[i]->ol_flags |= RTE_MBUF_F_RX_FDIR_ID;
        }
        /**
         * 以出口在 devices.ports 中的数组下标分组，指针相减得到元素间距
         * 例：ports[0].port_id = 1、ports[1].port_id = 5，出口为网口 5 时 index 为 1
         * tx[index]、tx_lengths[index]、counts[index] 和 outputs[index] 都属于这个出口
         */
        uint16_t index = (uint16_t)(egress - runtime->devices.ports);
        /**
         * 多段报文且出口未启用多段发送时，尝试将全部数据合并到第一段
         * 第一段空间不足等原因导致合并失败时，统计并释放当前包，继续处理下一个
         */
        if (rx[i]->nb_segs > 1U && (egress->configured_tx_offloads & RTE_ETH_TX_OFFLOAD_MULTI_SEGS) == 0 &&
            rte_pktmbuf_linearize(rx[i]) != 0) {
            outputs[index].tx_drops++;
            outputs[index].tx_linearize_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 将当前包追加到对应出口的待发送批次，只保存指针，此处尚未交给驱动
         * 提前保存长度供发送统计使用，成功提交后不再读取已转移所有权的 mbuf
         * 例：counts[index] 为 2，长度和指针都写入下标 2，然后 counts[index] 增为 3
         * counts 只统计本次 process_batch 收集的包，本批处理结束就发送，不等待凑满
         */
        tx_lengths[index][counts[index]] = length;
        tx[index][counts[index]++] = rx[i];
    }
    /** 接收批次内所有路径都会汇合到这里，先提交 COUNT 再发送或报告 QSBR 静默 */
    dppd_software_count_batch_flush(&rule_counts);
    /** 逐包处理已完成，进入本文件的 flush_egress，按出口提交各自的待发送批次 */
    for (uint16_t index = 0; index < runtime->devices.nb_ports; ++index)
        flush_egress(worker, &runtime->devices.ports[index], tx[index], tx_lengths[index], counts[index], &delta, &outputs[index]);
    /**
     * 此时 delta 保存本批入口接收和处理中的丢弃统计，outputs 按出口保存发送及发送失败统计
     * 先将 delta 记入入口网口，再将各 outputs 记入对应出口，并合并到 delta 供 worker 汇总
     * 例：入口 0 收到 3 包，均送往出口 1，其中 2 包提交成功、1 包因发送队列未接收而丢弃
     *   入口 0：RX 加 3；出口 1：TX 加 2、tx_queue_drops 加 1；worker 汇总包含这三项
     */
    dppd_stats_add(&worker->port_stats[ingress - runtime->devices.ports], &delta);
    for (uint16_t index = 0; index < runtime->devices.nb_ports; ++index) {
        dppd_stats_add(&worker->port_stats[index], &outputs[index]);
        dppd_stats_accumulate(&delta, &outputs[index]);
    }
    /** 每批只更新一次工作线程汇总，避免入口丢弃已累计而出口字节还没累计的额外窗口 */
    dppd_stats_add(&worker->stats, &delta);
}

int dppd_packet_parse_mbuf(const struct rte_mbuf *mbuf, struct dppd_packet *packet)
{
    uint8_t scratch[DPPD_HEADER_SCRATCH];
    uint32_t packet_len;
    uint32_t read_len;
    const void *data;

    if (mbuf == NULL || packet == NULL)
        return DPPD_PARSE_MALFORMED;

    /** packet_len 是整条 mbuf 链的总长度，read_len 取总长度与缓冲区上限中的较小值 */
    packet_len = rte_pktmbuf_pkt_len(mbuf);
    read_len = packet_len < sizeof(scratch) ? packet_len : sizeof(scratch);
    /**
     * 用于安全、连续地读取网络报文数据（mbuf）的核心函数
     * 连续时返回mbuf原始报文数据指针，零拷贝且不写 scratch
     * 跨段时将 read_len 个字节复制到 scratch，再返回其数据指针，发生拷贝
     * 返回值指向报文字节而非 struct rte_mbuf 管理结构，实际读取位置统一以 data 为准
     */
    data = rte_pktmbuf_read(mbuf, 0, read_len, scratch);
    if (data == NULL)
        return DPPD_PARSE_MALFORMED;
    /** 在局部缓冲区失效前完成解析；输出只保存字段值，不把 data 指针带出函数 */
    return dppd_packet_parse_buffer(data, read_len, packet_len, packet);
}

static void routed_decide(struct dppd_runtime *runtime, uint16_t ingress, int parsed, const struct dppd_packet *packet,
    struct dppd_pipeline_decision *decision, struct dppd_software_count_batch *counts)
{
    dppd_pipeline_decide_counted(&runtime->snapshot, runtime->software_backend, runtime->ipv4_router, ingress, parsed,
        packet, decision, counts);
    if (runtime->nd6 == NULL || packet->l3_type != DPPD_L3_IPV6)
        return;
    /**
     * 静态邻居未命中时，pipeline 返回 DROP / NO_NEIGHBOR，但已留下出口和下一跳
     * 上方检查保证此处是 IPv6 且已启用 ND（IPv6 邻居发现）
     *
     * 沿用示例：
     *   decision->ipv4.port_id = 1，next_hop6 = fe80::1，destination_mac 仍为全 0
     *   用网口 1 和 fe80::1 查询 ND 动态邻居表
     *   若找到可用 MAC，dppd_nd6_resolve 直接写入 decision->ipv4.destination_mac
     * 静态表没有邻居，并不代表动态表也没有，因此这里还需再查一次
     */
    if (decision->drop_reason == DPPD_DROP_NO_NEIGHBOR) {
        int rc = dppd_nd6_resolve(runtime->nd6, decision->ipv4.port_id, decision->ipv4.next_hop6, packet,
            dppd_monotonic_ms(), decision->ipv4.destination_mac);

        /**
         * rc = 0       → MAC 已写入，改为 FORWARD，填写出口并设置 routed
         * rc = -EAGAIN → MAC 尚未取得，改为 ND_PENDING，让 process_batch 尝试暂存报文
         * 其他错误     → 保持 DROP / NO_NEIGHBOR，交回调用方处理失败
         * ND_PENDING 时 action 仍是 DROP，但 process_batch 会先处理等待入队，再判断丢弃
         */
        if (rc == 0) {
            decision->action = DPPD_PACKET_FORWARD;
            decision->drop_reason = DPPD_DROP_NONE;
            decision->egress_port = decision->ipv4.port_id;
            decision->routed = true;
        } else if (rc == -EAGAIN)
            decision->drop_reason = DPPD_DROP_ND_PENDING;
    }
    /** 取得下一跳 MAC 后，仍须确认出口 IPv6 地址已就绪，否则改为 DROP / ND_NOT_READY */
    if (decision->action == DPPD_PACKET_FORWARD && !dppd_nd6_port_ready(runtime->nd6, decision->egress_port)) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_ND_NOT_READY;
    }
}

void dppd_pipeline_decide_counted(const struct dppd_forwarding_snapshot *snapshot,
    struct dppd_software_backend *software_backend, struct dppd_ipv4_router *router, uint16_t ingress_port,
    int parse_status, const struct dppd_packet *packet, struct dppd_pipeline_decision *decision,
    struct dppd_software_count_batch *counts)
{
    /**
     * memset 清零 → action = 0 → DROP，枚举定义在 pipeline.h
     * 初始保留 DROP，只有后续规则允许并选出出口才设置 FORWARD
     */
    memset(decision, 0, sizeof(*decision));

    /** 畸形报文字段不可信，直接判定丢弃，禁止继续匹配规则 */
    if (parse_status == DPPD_PARSE_MALFORMED) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_MALFORMED;
        return;
    }
    /** 软件后端存在时检查规则动作，后端为空则继续后面的出口选择 */
    if (software_backend != NULL && packet != NULL) {
        struct dppd_software_decision software_decision;

        /**
         * 软件规则 → software_decision；drop 为真时将最终 decision 设为 DROP/POLICY
         * 本例 IPv4 返回路径：本函数 → worker.c/routed_decide → process_batch
         *   → 更新丢弃统计 → 释放当前 mbuf → continue 下一个包
         * 未丢弃时携带 MARK 继续选出口；COUNT 按命中累计，后续失败不撤销
         */
        dppd_software_backend_decide_counted(software_backend, ingress_port, packet, &software_decision, counts);
        if (software_decision.drop) {
            decision->action = DPPD_PACKET_DROP;
            decision->drop_reason = DPPD_DROP_POLICY;
            return;
        }
        decision->has_mark = software_decision.has_mark;
        decision->mark_id = software_decision.mark_id;
    }
    /**
     * router 非空 → 校验 IP 类型 → 按目的 IP 查询路由和下一跳邻居
     *   成功 → 写入 FORWARD、出口和 routed = true → 返回
     *   失败 → 保留默认 DROP，填写失败原因 → 返回
     * router 为空 → 查询下面的静态端口配对
     * 两种出口选择方式由 router 是否为空决定，路由失败不回退到端口配对
     */
    if (router != NULL) {
        if (packet == NULL || (packet->l3_type != DPPD_L3_IPV4 && packet->l3_type != DPPD_L3_IPV6)) {
            decision->drop_reason = DPPD_DROP_IPV4_UNSUPPORTED;
            return;
        }
        bool ipv6 = packet->l3_type == DPPD_L3_IPV6;
        /** 两种地址族共用 decision->ipv4 保存查询得到的出口、下一跳和目的 MAC */
        int rc = ipv6 ? dppd_ipv6_router_lookup(router, packet->ipv6_dst, &decision->ipv4)
                      : dppd_ipv4_router_lookup(router, packet->ipv4_dst_be, &decision->ipv4);
        /**
         * 查询失败时 action 仍为默认 DROP，这里把错误码转换成原因后返回 routed_decide
         * IPv6 示例：路由已命中，静态邻居未命中，rc 为 -EHOSTUNREACH
         *   decision->ipv4 已有出口和下一跳 → drop_reason 写为 NO_NEIGHBOR
         *   返回 worker.c/routed_decide → 若启用 ND，再尝试从动态邻居表取得 MAC
         * 此处的 DROP / NO_NEIGHBOR 尚未释放 mbuf，后续可能改为转发或等待邻居
         */
        if (rc != 0) {
            decision->drop_reason = rc == -ENOENT ? DPPD_DROP_NO_ROUTE
                : rc == -EHOSTUNREACH             ? DPPD_DROP_NO_NEIGHBOR
                : ipv6                            ? DPPD_DROP_IPV6_UNSUPPORTED
                                                  : DPPD_DROP_IPV4_UNSUPPORTED;
            return;
        }
        decision->action = DPPD_PACKET_FORWARD;
        decision->egress_port = decision->ipv4.port_id;
        /** 标记需按三层结果改写报文，实际改写和发送由后续调用方执行 */
        decision->routed = true;
        return;
    }
    /**
     * router 为空 → lib/control/snapshot.c 按入口查端口配对，写入 decision->egress_port
     * 查到后设置 FORWARD；未查到则 DROP/NO_ROUTE，三层路由失败不回退到此处
     */
    if (dppd_snapshot_lookup_peer(snapshot, ingress_port, &decision->egress_port) != 0) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_NO_ROUTE;
        return;
    }

    decision->action = DPPD_PACKET_FORWARD;
    decision->drop_reason = DPPD_DROP_NONE;
}

static void process_batch(struct dppd_worker *worker, const struct dppd_port *ingress, struct rte_mbuf **rx,
    uint16_t received, bool retry, uint64_t expires)
{
    struct dppd_runtime *runtime = worker->runtime;
    /** 按出口暂存待发送的 mbuf 指针、长度和数量，逐包处理结束后统一批量发送 */
    struct rte_mbuf *tx[DPPD_MAX_PORTS][DPPD_MAX_BURST];
    uint32_t tx_lengths[DPPD_MAX_PORTS][DPPD_MAX_BURST];
    uint16_t counts[DPPD_MAX_PORTS] = {0};
    struct dppd_stats_values delta = {0}, outputs[DPPD_MAX_PORTS] = {0};
    struct dppd_software_count_batch rule_counts = {0};
    if (worker_io_quiesced(worker)) {
        /** RX 返回的报文已归线程所有，事件不能让这批 mbuf 因提前返回而泄漏 */
        free_packets(rx, received);
        return;
    }
    if (received == 0)
        return;
    delta.rx_packets = retry ? 0 : received;
    const struct dppd_port *paired =
        runtime->ipv4_router == NULL ? dppd_devices_find(&runtime->devices, ingress->peer_port_id) : NULL;
    for (uint16_t i = 0; i < received; ++i) {
        /** packet 保存解析字段，decision 保存处理决定，rx[i] 指向原始报文 */
        struct dppd_pipeline_decision decision;
        struct dppd_packet packet = {0};
        uint32_t length = rte_pktmbuf_pkt_len(rx[i]);
        if (!retry)
            delta.rx_bytes += length;
        /** 逐包进入 packet_mbuf.c 提取报文头字段，burst 只批量收发，不省略逐包解析 */
        int parsed = dppd_packet_parse_mbuf(rx[i], &packet);
        packet.neighbor_retry = retry;
        /** 隧道统计是外层中转观察，既不替换 ACL 字段，也不因内层错误改变已有放行结果 */
        if (!retry) {
            delta.tunnel_vxlan_packets += packet.tunnel.type == DPPD_TUNNEL_VXLAN;
            delta.tunnel_geneve_packets += packet.tunnel.type == DPPD_TUNNEL_GENEVE;
            delta.tunnel_gre_packets += packet.tunnel.type == DPPD_TUNNEL_GRE;
            delta.tunnel_malformed += packet.tunnel.status == DPPD_PARSE_MALFORMED;
            delta.tunnel_unsupported += packet.tunnel.status == DPPD_PARSE_UNSUPPORTED;
        }
        if (parsed == DPPD_PARSE_MALFORMED)
            delta.rx_malformed++;
        else if (parsed == DPPD_PARSE_UNSUPPORTED)
            delta.rx_unsupported++;
        if (runtime->nd6 != NULL && parsed != DPPD_PARSE_MALFORMED &&
            dppd_nd6_input(runtime->nd6, ingress->port_id, rx[i], &packet, dppd_monotonic_ms(), send_nd6, worker)) {
            delta.nd6_rx_packets++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        if (packet.l3_type == DPPD_L3_IPV6 && !dppd_nd6_port_ready(runtime->nd6, ingress->port_id)) {
            delta.nd6_not_ready_drops++;
            delta.policy_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 未启用连接跟踪
         *   → routed_decide → decision
         *
         * 启用连接跟踪
         *   → stateful_decide
         *       校验、准备候选会话
         *         → routed_decide
         *         → 检查出口、改写实际报文
         *         → 成功提交会话，失败取消候选
         */
        if (runtime->conntrack != NULL)
            stateful_decide(worker, ingress, &rx[i], parsed, &packet, &decision, &rule_counts);
        else
            routed_decide(runtime, ingress->port_id, parsed, &packet, &decision, &rule_counts);

        /**
         * ND_PENDING 表示下一跳 MAC 尚未取得，先尝试把当前 mbuf 交给 ND 等待队列
         * 入队成功 → 队列接管 mbuf，continue 处理下一个包，此处不能释放或发送它
         * 入队失败 → mbuf 仍归当前线程，继续下面的丢弃分支并释放
         */
        if (decision.drop_reason == DPPD_DROP_ND_PENDING) {
            struct dppd_nd6_pending pending = {.mbuf = rx[i],
                .ingress = ingress->port_id,
                .queue = worker->queue_id,
                .expires_ms = expires};
            if (dppd_nd6_hold(runtime->nd6, decision.ipv4.port_id, decision.ipv4.next_hop6, pending,
                    dppd_monotonic_ms()) == 0) {
                delta.nd6_queued++;
                continue;
            }
            delta.nd6_queue_drops++;
        }
        /**
         * 决定函数只填写结果，worker 在这里执行丢弃并按原因更新统计
         * 释放当前报文后继续处理本批下一个包，不影响其他报文
         */
        if (decision.action != DPPD_PACKET_FORWARD) {
            if (decision.drop_reason != DPPD_DROP_MALFORMED)
                delta.policy_drops++;
            if (decision.drop_reason == DPPD_DROP_ND_NOT_READY)
                delta.nd6_not_ready_drops++;
            else if (decision.drop_reason == DPPD_DROP_POLICY)
                delta.rule_drops++;
            else if (decision.drop_reason == DPPD_DROP_NO_ROUTE)
                delta.no_route_drops++;
            else if (decision.drop_reason == DPPD_DROP_NO_NEIGHBOR)
                delta.no_neighbor_drops++;
            else if (decision.drop_reason == DPPD_DROP_IPV4_UNSUPPORTED)
                delta.ipv4_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_IPV6_UNSUPPORTED)
                delta.ipv6_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_INVALID)
                delta.ct_invalid_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_FULL)
                delta.ct_full_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_UNSUPPORTED)
                delta.ct_unsupported_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_ZONE)
                delta.ct_zone_drops++;
            else if (decision.drop_reason == DPPD_DROP_CT_CHECKSUM)
                delta.ct_checksum_drops++;
            else if (decision.drop_reason == DPPD_DROP_NAT_POOL)
                delta.nat_pool_drops++;
            else if (decision.drop_reason == DPPD_DROP_NAT_MISS)
                delta.nat_miss_drops++;
            else if (decision.drop_reason == DPPD_DROP_TTL) {
                if (packet.l3_type == DPPD_L3_IPV6)
                    delta.ipv6_hop_drops++;
                else
                    delta.ipv4_ttl_drops++;
            } else if (decision.drop_reason == DPPD_DROP_REWRITE) {
                if (packet.l3_type == DPPD_L3_IPV6)
                    delta.ipv6_rewrite_drops++;
                else
                    delta.ipv4_rewrite_drops++;
            } else if (decision.drop_reason == DPPD_DROP_EGRESS)
                delta.egress_drops++;
            /** 归还当前 mbuf，再进入逐包循环的下一轮 */
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 根据处理决定取得实际出口对象，三层模式按出口编号查找，端口配对模式复用 paired
         * FORWARD 只表示策略允许，发送前仍须确认出口存在、编号一致且可发送
         */
        const struct dppd_port *egress =
            runtime->ipv4_router != NULL ? dppd_devices_find(&runtime->devices, decision.egress_port) : paired;
        if (egress == NULL || egress->port_id != decision.egress_port || !dppd_port_tx_available(egress)) {
            delta.policy_drops++;
            delta.egress_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 三层转发在这里改写报文头，启用连接跟踪时已由 stateful_decide 改写，不能再次递减跳数
         * IPv6 普通转发：目的 MAC 改为下一跳 MAC，源 MAC 改为出口 MAC，Hop Limit 减 1
         *
         * &rx[i] 允许改写函数在需要复制报文时替换 mbuf 指针，后续发送使用替换后的指针
         * &packet 提供已解析的头部信息，decision.ipv4 是 IPv4/IPv6 共用的转发结果
         * 改写失败则释放当前包；成功后继续加入出口发送批次，此处尚未交给网卡
         */
        if (decision.routed && runtime->conntrack == NULL) {
            bool ipv6 = packet.l3_type == DPPD_L3_IPV6;
            int rc = ipv6 ? dppd_ipv6_rewrite(&rx[i], &packet, &decision.ipv4, egress->mac.addr_bytes)
                          : dppd_ipv4_rewrite(&rx[i], &packet, &decision.ipv4, egress->mac.addr_bytes);
            if (rc != 0) {
                delta.policy_drops++;
                if (ipv6) {
                    if (rc == -ETIMEDOUT)
                        delta.ipv6_hop_drops++;
                    else if (rc == -EBADMSG)
                        delta.ipv6_checksum_drops++;
                    else if (rc == -ENOTSUP)
                        delta.ipv6_unsupported_drops++;
                    else
                        delta.ipv6_rewrite_drops++;
                } else if (rc == -ETIMEDOUT)
                    delta.ipv4_ttl_drops++;
                else if (rc == -EBADMSG)
                    delta.ipv4_checksum_drops++;
                else if (rc == -ENOTSUP)
                    delta.ipv4_unsupported_drops++;
                else
                    delta.ipv4_rewrite_drops++;
                rte_pktmbuf_free(rx[i]);
                continue;
            }
        }
        /** 将规则 MARK 写入 mbuf 的附加信息并设置有效标志，不向报文字节中插入标记 */
        if (decision.has_mark) {
            rx[i]->hash.fdir.hi = decision.mark_id;
            rx[i]->ol_flags |= RTE_MBUF_F_RX_FDIR_ID;
        }
        /**
         * 以出口在 devices.ports 中的数组下标分组，指针相减得到元素间距
         * 例：ports[0].port_id = 1、ports[1].port_id = 5，出口为网口 5 时 index 为 1
         * tx[index]、tx_lengths[index]、counts[index] 和 outputs[index] 都属于这个出口
         */
        uint16_t index = (uint16_t)(egress - runtime->devices.ports);
        /**
         * 多段报文且出口未启用多段发送时，尝试将全部数据合并到第一段
         * 第一段空间不足等原因导致合并失败时，统计并释放当前包，继续处理下一个
         */
        if (rx[i]->nb_segs > 1U && (egress->configured_tx_offloads & RTE_ETH_TX_OFFLOAD_MULTI_SEGS) == 0 &&
            rte_pktmbuf_linearize(rx[i]) != 0) {
            outputs[index].tx_drops++;
            outputs[index].tx_linearize_drops++;
            rte_pktmbuf_free(rx[i]);
            continue;
        }
        /**
         * 将当前包追加到对应出口的待发送批次，只保存指针，此处尚未交给驱动
         * 提前保存长度供发送统计使用，成功提交后不再读取已转移所有权的 mbuf
         * 例：counts[index] 为 2，长度和指针都写入下标 2，然后 counts[index] 增为 3
         * counts 只统计本次 process_batch 收集的包，本批处理结束就发送，不等待凑满
         */
        tx_lengths[index][counts[index]] = length;
        tx[index][counts[index]++] = rx[i];
    }
    /** 接收批次内所有路径都会汇合到这里，先提交 COUNT 再发送或报告 QSBR 静默 */
    dppd_software_count_batch_flush(&rule_counts);
    /** 逐包处理已完成，进入本文件的 flush_egress，按出口提交各自的待发送批次 */
    for (uint16_t index = 0; index < runtime->devices.nb_ports; ++index)
        flush_egress(worker, &runtime->devices.ports[index], tx[index], tx_lengths[index], counts[index], &delta, &outputs[index]);
    /**
     * 此时 delta 保存本批入口接收和处理中的丢弃统计，outputs 按出口保存发送及发送失败统计
     * 先将 delta 记入入口网口，再将各 outputs 记入对应出口，并合并到 delta 供 worker 汇总
     * 例：入口 0 收到 3 包，均送往出口 1，其中 2 包提交成功、1 包因发送队列未接收而丢弃
     *   入口 0：RX 加 3；出口 1：TX 加 2、tx_queue_drops 加 1；worker 汇总包含这三项
     */
    dppd_stats_add(&worker->port_stats[ingress - runtime->devices.ports], &delta);
    for (uint16_t index = 0; index < runtime->devices.nb_ports; ++index) {
        dppd_stats_add(&worker->port_stats[index], &outputs[index]);
        dppd_stats_accumulate(&delta, &outputs[index]);
    }
    /** 每批只更新一次工作线程汇总，避免入口丢弃已累计而出口字节还没累计的额外窗口 */
    dppd_stats_add(&worker->stats, &delta);
}

int dppd_packet_parse_mbuf(const struct rte_mbuf *mbuf, struct dppd_packet *packet)
{
    uint8_t scratch[DPPD_HEADER_SCRATCH];
    uint32_t packet_len;
    uint32_t read_len;
    const void *data;

    if (mbuf == NULL || packet == NULL)
        return DPPD_PARSE_MALFORMED;

    /** packet_len 是整条 mbuf 链的总长度，read_len 取总长度与缓冲区上限中的较小值 */
    packet_len = rte_pktmbuf_pkt_len(mbuf);
    read_len = packet_len < sizeof(scratch) ? packet_len : sizeof(scratch);
    /**
     * 用于安全、连续地读取网络报文数据（mbuf）的核心函数
     * 连续时返回mbuf原始报文数据指针，零拷贝且不写 scratch
     * 跨段时将 read_len 个字节复制到 scratch，再返回其数据指针，发生拷贝
     * 返回值指向报文字节而非 struct rte_mbuf 管理结构，实际读取位置统一以 data 为准
     */
    data = rte_pktmbuf_read(mbuf, 0, read_len, scratch);
    if (data == NULL)
        return DPPD_PARSE_MALFORMED;
    /** 在局部缓冲区失效前完成解析；输出只保存字段值，不把 data 指针带出函数 */
    return dppd_packet_parse_buffer(data, read_len, packet_len, packet);
}

int dppd_packet_parse_mbuf(const struct rte_mbuf *mbuf, struct dppd_packet *packet)
{
    uint8_t scratch[DPPD_HEADER_SCRATCH];
    uint32_t packet_len;
    uint32_t read_len;
    const void *data;

    if (mbuf == NULL || packet == NULL)
        return DPPD_PARSE_MALFORMED;

    /** packet_len 是整条 mbuf 链的总长度，read_len 取总长度与缓冲区上限中的较小值 */
    packet_len = rte_pktmbuf_pkt_len(mbuf);
    read_len = packet_len < sizeof(scratch) ? packet_len : sizeof(scratch);
    /**
     * 用于安全、连续地读取网络报文数据（mbuf）的核心函数
     * 连续时返回mbuf原始报文数据指针，零拷贝且不写 scratch
     * 跨段时将 read_len 个字节复制到 scratch，再返回其数据指针，发生拷贝
     * 返回值指向报文字节而非 struct rte_mbuf 管理结构，实际读取位置统一以 data 为准
     */
    data = rte_pktmbuf_read(mbuf, 0, read_len, scratch);
    if (data == NULL)
        return DPPD_PARSE_MALFORMED;
    /** 在局部缓冲区失效前完成解析；输出只保存字段值，不把 data 指针带出函数 */
    return dppd_packet_parse_buffer(data, read_len, packet_len, packet);
}

int dppd_packet_parse_buffer(const uint8_t *data, uint32_t available_len, uint32_t packet_len,
    struct dppd_packet *packet)
{
    int rc = dppd_packet_parse_headers(data, available_len, packet_len, packet);
    if (rc == DPPD_PARSE_OK)
        (void)dppd_tunnel_parse_buffer(data, available_len, packet_len, packet);
    return rc;
}

int dppd_packet_parse_headers(const uint8_t *data, uint32_t available_len, uint32_t packet_len,
    struct dppd_packet *packet)
{
    uint32_t offset;
    uint16_t ether_type;

    if (data == NULL || packet == NULL || require_bytes(0, DPPD_ETHER_HEADER_LEN, available_len, packet_len) != 0)
        return DPPD_PARSE_MALFORMED;

    /** 初始以太网头检查成功后才清零输出，后续未解析的字段保持默认值 */
    memset(packet, 0, sizeof(*packet));
    packet->connection_state = DPPD_CT_UNTRACKED;
    packet->packet_len = packet_len;
    packet->l2_len = DPPD_ETHER_HEADER_LEN;
    /**
     * 无 VLAN 的 IPv4 报文布局
     * 整包偏移   0～5         6～11        12～13       14 开始
     * 内容       目的 MAC     源 MAC       协议类型      IPv4 头
     *            └──────── 以太网头 14 字节 ────────┘
     */
    ether_type = read_be16(data + 12U);
    offset = DPPD_ETHER_HEADER_LEN;

    /** 每层标签包含 TCI 和下一层协议类型，逐层跳过，最多读取两层 */
    while ((ether_type == DPPD_ETHER_TYPE_VLAN || ether_type == DPPD_ETHER_TYPE_QINQ) && packet->vlan_depth < 2U) {
        if (require_bytes(offset, DPPD_VLAN_HEADER_LEN, available_len, packet_len) != 0)
            return DPPD_PARSE_MALFORMED;
        packet->vlan_tpid[packet->vlan_depth] = ether_type;
        packet->vlan_tci[packet->vlan_depth++] = read_be16(data + offset);
        ether_type = read_be16(data + offset + 2U);
        offset += DPPD_VLAN_HEADER_LEN;
        packet->l2_len = (uint16_t)offset;
    }

    /** 两层之后仍是 VLAN 表示超出当前支持范围，不能误把下一层标签当作 IP 头 */
    if (ether_type == DPPD_ETHER_TYPE_VLAN || ether_type == DPPD_ETHER_TYPE_QINQ)
        return DPPD_PARSE_UNSUPPORTED;

    packet->ether_type = ether_type;
    /** ARP 这里只检查常见格式所需的 28 字节并记录类型，不进一步校验或提取其内部字段 */
    if (ether_type == DPPD_ETHER_TYPE_ARP) {
        if (require_bytes(offset, DPPD_ARP_HEADER_LEN, available_len, packet_len) != 0)
            return DPPD_PARSE_MALFORMED;
        packet->l3_type = DPPD_L3_ARP;
        packet->l3_len = DPPD_ARP_HEADER_LEN;
        return DPPD_PARSE_OK;
    }

    if (ether_type == 0x86ddU)
        return dppd_ipv6_parse(data, available_len, packet_len, packet);
    /** 其他以太网协议暂不深入解析，这种情况与报文头被截断不同 */
    if (ether_type != DPPD_ETHER_TYPE_IPV4)
        return DPPD_PARSE_UNSUPPORTED;

    {
        uint16_t total_length;
        uint16_t fragment;
        uint8_t ihl;
        uint8_t protocol;

        if (require_bytes(offset, DPPD_IPV4_MIN_HEADER_LEN, available_len, packet_len) != 0)
            return DPPD_PARSE_MALFORMED;
        /**
         * IPv4 首字节同时保存版本与 IHL，IHL 以 4 字节为单位
         * 0x45 = 0100 0101
         *        └──┘ └──┘
         *        版本 IHL
         *         4    5 × 4 = 20 字节
         * IHL 包含选项长度，后续按实际头长检查可读范围
         */
        if ((data[offset] >> 4) != 4U)
            return DPPD_PARSE_MALFORMED;
        ihl = (uint8_t)((data[offset] & 0x0fU) * 4U);
        if (ihl < DPPD_IPV4_MIN_HEADER_LEN || require_bytes(offset, ihl, available_len, packet_len) != 0)
            return DPPD_PARSE_MALFORMED;

        /**
         * IP 头偏移 2 处的两字节是总长度，包含 IP 头和负载，须介于头长与整包剩余长度之间
         * 本例：[以太网头 14][IPv4 头 20 | UDP 头 8 | 数据 18]
         * 整包 packet_len = 60，IP 总长 total_length = 46，IP 头长 ihl = 20
         * 不要求全部负载位于当前连续缓冲区，IP 声明范围以整包长度校验
         * 以太网帧末尾可能有填充，因此允许 IP 总长度小于整包剩余长度
         */
        total_length = read_be16(data + offset + 2U);
        if (total_length < ihl || total_length > packet_len - offset)
            return DPPD_PARSE_MALFORMED;

        packet->l3_type = DPPD_L3_IPV4;
        packet->l3_len = ihl;
        packet->ipv4_total_len = total_length;
        /**
         * IP 头内偏移   9         12..15       16..19
         * 字段          协议号    源地址       目的地址
         * 本例：源地址起点 14 + 12 = 26，UDP 头起点 14 + 20 = 34
         * 地址原样复制，保留网络字节序并避免未对齐访问
         */
        protocol = data[offset + 9U];
        packet->ip_protocol = protocol;
        memcpy(&packet->ipv4_src_be, data + offset + 12U, sizeof(packet->ipv4_src_be));
        memcpy(&packet->ipv4_dst_be, data + offset + 16U, sizeof(packet->ipv4_dst_be));
        fragment = read_be16(data + offset + 6U);
        offset += ihl;

        /**
         * 分片字段：[保留 1 位][DF 1 位][MF 1 位][分片偏移 13 位]
         * DF：禁止分片；MF：还有后续分片
         * MF = 1 或分片偏移非零 → 标记 FRAGMENT，返回 OK
         * 首片带有 UDP/TCP 头，也不提取端口，与后续分片统一处理
         */
        packet->ipv4_more_fragments = (fragment & DPPD_IPV4_MORE_FRAGMENTS) != 0;
        if ((fragment & (DPPD_IPV4_MORE_FRAGMENTS | DPPD_IPV4_OFFSET_MASK)) != 0) {
            packet->l4_type = DPPD_L4_FRAGMENT;
            return DPPD_PARSE_OK;
        }

        if (protocol == DPPD_IPPROTO_UDP) {
            /**
             * 本例：[IP 头 20][UDP 头 8 | 数据 18]，IP 总长 46
             * l4_available = 46 - 20 = 26，包含 UDP 头和 UDP 数据
             * 以 IP 声明的长度为上限，避免把以太网填充算作 UDP 数据
             */
            const uint32_t l4_available = (uint32_t)total_length - ihl;
            uint16_t udp_length;

            if (l4_available < DPPD_UDP_HEADER_LEN ||
                require_bytes(offset, DPPD_UDP_HEADER_LEN, available_len, packet_len) != 0)
                return DPPD_PARSE_MALFORMED;
            /**
             * UDP 头内偏移   0..1      2..3      4..5      6..7
             * 字段          源端口    目的端口  UDP 总长  校验和
             * UDP 头固定 8 字节，长度字段包含头和数据，本例为 8 + 18 = 26
             * UDP 总长不能小于头长，也不能超过 IP 负载长度 l4_available
             */
            udp_length = read_be16(data + offset + 4U);
            if (udp_length < DPPD_UDP_HEADER_LEN || udp_length > l4_available)
                return DPPD_PARSE_MALFORMED;
            packet->l4_type = DPPD_L4_UDP;
            packet->l4_len = DPPD_UDP_HEADER_LEN;
            /**
             * 本例整包偏移：[34..35 源端口][36..37 目的端口]
             * 端口以网络字节序复制到 packet，修改副本不会写回原始报文
             */
            memcpy(&packet->l4_src_port_be, data + offset, sizeof(packet->l4_src_port_be));
            memcpy(&packet->l4_dst_port_be, data + offset + 2U, sizeof(packet->l4_dst_port_be));
            return DPPD_PARSE_OK;
        }

        if (protocol == DPPD_IPPROTO_TCP) {
            const uint32_t l4_available = (uint32_t)total_length - ihl;
            uint8_t tcp_length;

            if (l4_available < DPPD_TCP_MIN_HEADER_LEN ||
                require_bytes(offset, DPPD_TCP_MIN_HEADER_LEN, available_len, packet_len) != 0)
                return DPPD_PARSE_MALFORMED;
            /**
             * TCP 数据偏移以 4 字节为单位给出头长，包含可选字段，最少为 20 字节
             * 同时检查 IP 负载上限和连续缓冲区边界，避免把不完整的选项区视为完整头部
             */
            tcp_length = (uint8_t)((data[offset + 12U] >> 4) * 4U);
            if (tcp_length < DPPD_TCP_MIN_HEADER_LEN || tcp_length > l4_available ||
                require_bytes(offset, tcp_length, available_len, packet_len) != 0)
                return DPPD_PARSE_MALFORMED;
            packet->l4_type = DPPD_L4_TCP;
            packet->l4_len = tcp_length;
            packet->tcp_flags = data[offset + 13U];
            memcpy(&packet->tcp_sequence_be, data + offset + 4U, 4);
            memcpy(&packet->tcp_acknowledgment_be, data + offset + 8U, 4);
            memcpy(&packet->l4_src_port_be, data + offset, sizeof(packet->l4_src_port_be));
            memcpy(&packet->l4_dst_port_be, data + offset + 2U, sizeof(packet->l4_dst_port_be));
            return DPPD_PARSE_OK;
        }

        /** 已识别出合法的 IPv4 头，但不是当前解析的 UDP 或 TCP，保留 IP 字段供后续使用 */
        packet->l4_type = DPPD_L4_OTHER;
        return DPPD_PARSE_OK;
    }
}

int dppd_packet_parse_buffer(const uint8_t *data, uint32_t available_len, uint32_t packet_len,
    struct dppd_packet *packet)
{
    int rc = dppd_packet_parse_headers(data, available_len, packet_len, packet);
    if (rc == DPPD_PARSE_OK)
        (void)dppd_tunnel_parse_buffer(data, available_len, packet_len, packet);
    return rc;
}

int dppd_packet_parse_mbuf(const struct rte_mbuf *mbuf, struct dppd_packet *packet)
{
    uint8_t scratch[DPPD_HEADER_SCRATCH];
    uint32_t packet_len;
    uint32_t read_len;
    const void *data;

    if (mbuf == NULL || packet == NULL)
        return DPPD_PARSE_MALFORMED;

    /** packet_len 是整条 mbuf 链的总长度，read_len 取总长度与缓冲区上限中的较小值 */
    packet_len = rte_pktmbuf_pkt_len(mbuf);
    read_len = packet_len < sizeof(scratch) ? packet_len : sizeof(scratch);
    /**
     * 用于安全、连续地读取网络报文数据（mbuf）的核心函数
     * 连续时返回mbuf原始报文数据指针，零拷贝且不写 scratch
     * 跨段时将 read_len 个字节复制到 scratch，再返回其数据指针，发生拷贝
     * 返回值指向报文字节而非 struct rte_mbuf 管理结构，实际读取位置统一以 data 为准
     */
    data = rte_pktmbuf_read(mbuf, 0, read_len, scratch);
    if (data == NULL)
        return DPPD_PARSE_MALFORMED;
    /** 在局部缓冲区失效前完成解析；输出只保存字段值，不把 data 指针带出函数 */
    return dppd_packet_parse_buffer(data, read_len, packet_len, packet);
}

static void routed_decide(struct dppd_runtime *runtime, uint16_t ingress, int parsed, const struct dppd_packet *packet,
    struct dppd_pipeline_decision *decision, struct dppd_software_count_batch *counts)
{
    dppd_pipeline_decide_counted(&runtime->snapshot, runtime->software_backend, runtime->ipv4_router, ingress, parsed,
        packet, decision, counts);
    if (runtime->nd6 == NULL || packet->l3_type != DPPD_L3_IPV6)
        return;
    /**
     * 静态邻居未命中时，pipeline 返回 DROP / NO_NEIGHBOR，但已留下出口和下一跳
     * 上方检查保证此处是 IPv6 且已启用 ND（IPv6 邻居发现）
     *
     * 沿用示例：
     *   decision->ipv4.port_id = 1，next_hop6 = fe80::1，destination_mac 仍为全 0
     *   用网口 1 和 fe80::1 查询 ND 动态邻居表
     *   若找到可用 MAC，dppd_nd6_resolve 直接写入 decision->ipv4.destination_mac
     * 静态表没有邻居，并不代表动态表也没有，因此这里还需再查一次
     */
    if (decision->drop_reason == DPPD_DROP_NO_NEIGHBOR) {
        int rc = dppd_nd6_resolve(runtime->nd6, decision->ipv4.port_id, decision->ipv4.next_hop6, packet,
            dppd_monotonic_ms(), decision->ipv4.destination_mac);

        /**
         * rc = 0       → MAC 已写入，改为 FORWARD，填写出口并设置 routed
         * rc = -EAGAIN → MAC 尚未取得，改为 ND_PENDING，让 process_batch 尝试暂存报文
         * 其他错误     → 保持 DROP / NO_NEIGHBOR，交回调用方处理失败
         * ND_PENDING 时 action 仍是 DROP，但 process_batch 会先处理等待入队，再判断丢弃
         */
        if (rc == 0) {
            decision->action = DPPD_PACKET_FORWARD;
            decision->drop_reason = DPPD_DROP_NONE;
            decision->egress_port = decision->ipv4.port_id;
            decision->routed = true;
        } else if (rc == -EAGAIN)
            decision->drop_reason = DPPD_DROP_ND_PENDING;
    }
    /** 取得下一跳 MAC 后，仍须确认出口 IPv6 地址已就绪，否则改为 DROP / ND_NOT_READY */
    if (decision->action == DPPD_PACKET_FORWARD && !dppd_nd6_port_ready(runtime->nd6, decision->egress_port)) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_ND_NOT_READY;
    }
}

