void dppd_pipeline_decide_counted(const struct dppd_forwarding_snapshot *snapshot,
    struct dppd_software_backend *software_backend, struct dppd_ipv4_router *router, uint16_t ingress_port,
    int parse_status, const struct dppd_packet *packet, struct dppd_pipeline_decision *decision,
    struct dppd_software_count_batch *counts)
{
    /**
     * memset 清零 → action = 0 → DROP，枚举定义在 pipeline.h
     * 初始保留 DROP，只有后续规则允许并选出出口才设置 FORWARD
     */
    memset(decision, 0, sizeof(*decision));

    /** 畸形报文字段不可信，直接判定丢弃，禁止继续匹配规则 */
    if (parse_status == DPPD_PARSE_MALFORMED) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_MALFORMED;
        return;
    }
    /** 软件后端存在时检查规则动作，后端为空则继续后面的出口选择 */
    if (software_backend != NULL && packet != NULL) {
        struct dppd_software_decision software_decision;

        /**
         * 软件规则 → software_decision；drop 为真时将最终 decision 设为 DROP/POLICY
         * 本例 IPv4 返回路径：本函数 → worker.c/routed_decide → process_batch
         *   → 更新丢弃统计 → 释放当前 mbuf → continue 下一个包
         * 未丢弃时携带 MARK 继续选出口；COUNT 按命中累计，后续失败不撤销
         */
        dppd_software_backend_decide_counted(software_backend, ingress_port, packet, &software_decision, counts);
        if (software_decision.drop) {
            decision->action = DPPD_PACKET_DROP;
            decision->drop_reason = DPPD_DROP_POLICY;
            return;
        }
        decision->has_mark = software_decision.has_mark;
        decision->mark_id = software_decision.mark_id;
    }
    /**
     * router 非空 → 校验 IP 类型 → 按目的 IP 查询路由和下一跳邻居
     *   成功 → 写入 FORWARD、出口和 routed = true → 返回
     *   失败 → 保留默认 DROP，填写失败原因 → 返回
     * router 为空 → 查询下面的静态端口配对
     * 两种出口选择方式由 router 是否为空决定，路由失败不回退到端口配对
     */
    if (router != NULL) {
        if (packet == NULL || (packet->l3_type != DPPD_L3_IPV4 && packet->l3_type != DPPD_L3_IPV6)) {
            decision->drop_reason = DPPD_DROP_IPV4_UNSUPPORTED;
            return;
        }
        bool ipv6 = packet->l3_type == DPPD_L3_IPV6;
        /** 两种地址族共用 decision->ipv4 保存查询得到的出口、下一跳和目的 MAC */
        int rc = ipv6 ? dppd_ipv6_router_lookup(router, packet->ipv6_dst, &decision->ipv4)
                      : dppd_ipv4_router_lookup(router, packet->ipv4_dst_be, &decision->ipv4);
        /**
         * 查询失败时 action 仍为默认 DROP，这里把错误码转换成原因后返回 routed_decide
         * IPv6 示例：路由已命中，静态邻居未命中，rc 为 -EHOSTUNREACH
         *   decision->ipv4 已有出口和下一跳 → drop_reason 写为 NO_NEIGHBOR
         *   返回 worker.c/routed_decide → 若启用 ND，再尝试从动态邻居表取得 MAC
         * 此处的 DROP / NO_NEIGHBOR 尚未释放 mbuf，后续可能改为转发或等待邻居
         */
        if (rc != 0) {
            decision->drop_reason = rc == -ENOENT ? DPPD_DROP_NO_ROUTE
                : rc == -EHOSTUNREACH             ? DPPD_DROP_NO_NEIGHBOR
                : ipv6                            ? DPPD_DROP_IPV6_UNSUPPORTED
                                                  : DPPD_DROP_IPV4_UNSUPPORTED;
            return;
        }
        decision->action = DPPD_PACKET_FORWARD;
        decision->egress_port = decision->ipv4.port_id;
        /** 标记需按三层结果改写报文，实际改写和发送由后续调用方执行 */
        decision->routed = true;
        return;
    }
    /**
     * router 为空 → lib/control/snapshot.c 按入口查端口配对，写入 decision->egress_port
     * 查到后设置 FORWARD；未查到则 DROP/NO_ROUTE，三层路由失败不回退到此处
     */
    if (dppd_snapshot_lookup_peer(snapshot, ingress_port, &decision->egress_port) != 0) {
        decision->action = DPPD_PACKET_DROP;
        decision->drop_reason = DPPD_DROP_NO_ROUTE;
        return;
    }

    decision->action = DPPD_PACKET_FORWARD;
    decision->drop_reason = DPPD_DROP_NONE;
}

void dppd_software_backend_decide_counted(struct dppd_software_backend *backend, uint16_t ingress_port,
    const struct dppd_packet *packet, struct dppd_software_decision *decision, struct dppd_software_count_batch *batch)
{
    struct dppd_software_classifier_snapshot *active;
    struct dppd_software_rule_object *selected = NULL;
    memset(decision, 0, sizeof(*decision));
    if (backend == NULL || packet == NULL)
        return;
    /**
     * backend->active → 本包的规则快照 active → ACL/精确匹配各自返回候选，0 表示未命中
     *
     * 读到这里可继续追查：active 中的规则是谁提前准备并发布进去的
     * 报文处理：process_batch → routed_decide → pipeline → 本函数读取 active，匹配当前包
     * 规则配置：control.c/dppd_control_apply → control_apply_impl → transaction_run
     *           → 软件 transaction_commit → publish_locked 构建匹配表并更新 backend->active
     * 两条流程通过同一个 backend->active 衔接；转去读配置入口是在追查规则来源，并非本函数调用它
     * 回到本函数后，继续用取得的同一快照查询下面的 ACL 和 exact 表
     *
     * 每包只取一次 active，两类匹配共用同一版本，不获取控制面写锁
     * 调用线程须已注册上线 QSBR，防止读取期间旧规则表被回收
     * acquire 与发布端 release 配对，保证读到新指针时规则内容也已可见
     */
    active = atomic_load_explicit(&backend->active, memory_order_acquire);
    /**
     * ACL 支持掩码、端口范围等条件；exact 对完整地址和端口组合做哈希查找
     * 各自返回本表优先命中的规则 tag，0 表示未命中，选定候选后再执行动作
     */
    uint32_t tag = dppd_acl_classify(snapshot_acl(active, backend->capacity), ingress_port, packet);
    uint32_t exact_tag = dppd_exact_classify(snapshot_exact(active, backend->capacity), ingress_port, packet);
    /**
     * ACL tag + exact_tag → 选定一个 tag
     * 单个命中 → 直接选用；两个都命中 → 按 rule_before 排序
     * tag = 0 → 无规则；tag > 0 → active->objects[tag - 1]，数组下标从 0 开始
     */
    if (exact_tag != 0 &&
        (tag == 0 || rule_before(&active->objects[exact_tag - 1].rule, exact_tag, &active->objects[tag - 1].rule, tag)))
        tag = exact_tag;
    if (tag != 0)
        selected = &active->objects[tag - 1];
    if (selected != NULL) {
        uint16_t action;

        /**
         * 只执行选中规则的动作，DROP/MARK 写入软件决策，COUNT 累计命中统计
         * R1 示例：[DROP, COUNT] → matched = true、drop = true，并累计本包次数和字节数
         * DROP 不退出循环，也不释放报文；释放由 worker.c/process_batch 按最终决策执行
         */
        decision->matched = true;
        for (action = 0; action < selected->rule.nb_actions; ++action) {
            const struct dppd_action *source = &selected->rule.actions[action];

            if (source->type == DPPD_ACTION_DROP)
                decision->drop = true;
            else if (source->type == DPPD_ACTION_MARK) {
                decision->has_mark = true;
                decision->mark_id = source->conf.mark_id;
            } else if (source->type == DPPD_ACTION_SHARED_COUNT && !packet->neighbor_retry) {
                atomic_fetch_add_explicit(&selected->metrics->shared->hits, 1, memory_order_relaxed);
                atomic_fetch_add_explicit(&selected->metrics->shared->bytes, packet->packet_len, memory_order_relaxed);
            } else if (source->type == DPPD_ACTION_COUNT && !packet->neighbor_retry)
                count_packet(selected->metrics, packet->packet_len, batch);
        }
    }
}

uint32_t dppd_acl_classify(const struct dppd_acl *acl, uint16_t ingress, const struct dppd_packet *packet)
{
    if (acl == NULL || packet == NULL)
        return 0;
    /**
     * 写入时先按 ingress 排序，同入口规则连续存放，内部按规则优先顺序排列
     * 在 [first, last) 内二分，找到首个 ingress >= 目标入口的位置
     * 入口示例：[0, 0, 1, 1, 1, 3]，查入口 1 → first = 2
     */
    uint32_t first = 0, last = acl->count;
    while (first < last) {
        uint32_t middle = first + (last - first) / 2;
        if (acl->rows[middle].ingress < ingress)
            first = middle + 1;
        else
            last = middle;
    }
    /** 只遍历目标入口的规则段，首条命中即返回，不再检查后续规则 */
    for (; first < acl->count && acl->rows[first].ingress == ingress; ++first)
        if (matches(&acl->rows[first], packet))
            return acl->rows[first].tag;
    return 0;
}

uint32_t dppd_exact_classify(const struct dppd_exact *table, uint16_t ingress, const struct dppd_packet *packet)
{
    if (table == NULL || table->capacity == 0 || packet == NULL ||
        (packet->l3_type != DPPD_L3_IPV4 && packet->l3_type != DPPD_L3_IPV6) ||
        (packet->l4_type != DPPD_L4_TCP && packet->l4_type != DPPD_L4_UDP))
        return 0;
    /**
     * 将报文字段组合成 40 字节查找键，下列偏移均相对 key 起点
     * 偏移  0～1   2       3       4～19    20～35   36～37   38～39
     * 内容  入口   地址族  传输层  源地址   目的地址 源端口   目的端口
     * 地址族和传输层使用项目枚举，地址和端口保留网络字节序
     * IPv4 地址各写 4 字节，其余地址空间保留为 0；IPv6 地址各写满 16 字节
     * 规则入表与报文查询使用同一布局，清零保证未使用字节也能一致比较
     */
    uint8_t key[EXACT_KEY_SIZE] = {0};
    key_prefix(key, ingress, (uint8_t)packet->l3_type, (uint8_t)packet->l4_type);
    if (packet->l3_type == DPPD_L3_IPV4) {
        memcpy(key + 4, &packet->ipv4_src_be, 4);
        memcpy(key + 20, &packet->ipv4_dst_be, 4);
    } else {
        memcpy(key + 4, packet->ipv6_src, 16);
        memcpy(key + 20, packet->ipv6_dst, 16);
    }
    memcpy(key + 36, &packet->l4_src_port_be, 2);
    memcpy(key + 38, &packet->l4_dst_port_be, 2);
    /**
     * 桶值和 next 均为行下标加一，0 表示链结束，与规则 tag 含义不同
     * 不同键可能落入同一桶，须比较完整 40 字节，不能仅凭哈希认定命中
     *
     * hash_key(key)                  → 算出哈希值
     * 哈希值 % table->capacity       → 得到桶下标
     * buckets(table)[桶下标]         → 取得桶内第一条规则的行编号
     * 沿桶值 4 → rows[3] → next 为 1 → rows[0] → next 为 0，结束
     */
    const struct exact_row *selected = NULL;
    for (uint32_t index = buckets(table)[hash_key(key) % table->capacity]; index != 0;) {
        const struct exact_row *row = &table->rows[index - 1];
        /** 同键规则可能有多条，保留优先的一条，不能遇到首次命中就返回 */
        if (memcmp(key, row->key, sizeof(key)) == 0 && (selected == NULL || before(row, selected)))
            selected = row;
        index = row->next;
    }
    /** 返回本精确表选出的候选 tag，无命中返回 0，交由软件后端与 ACL 候选比较 */
    return selected == NULL ? 0 : selected->tag;
}

if (exact_tag != 0 &&
    (tag == 0 || rule_before(&active->objects[exact_tag - 1].rule, exact_tag, &active->objects[tag - 1].rule, tag)))
