for (struct rte_mbuf *part = writable; part != NULL; part = part->next)
    if (!RTE_MBUF_DIRECT(part) || RTE_MBUF_HAS_EXTBUF(part) || rte_mbuf_refcnt_read(part) != 1) {
        /** 若目标是新副本，只清理副本，原报文仍交由调用方处理 */
        if (copy)
            rte_pktmbuf_free(writable);
        return -ENOTSUP;
    }

if (copy) {
