        &repository_result);
    if (rc != 0) {
        /* 单控制线程下不应到达这里；到达即表示 actual/desired 已失配 */
        dppd_rule_observation_fault(&service->observation, rc);
        return isolate_control(service, rc);
    }
    service->observation.applied = true;
    result->status = repository_result.status;
    result->generation = repository_result.generation;
    rc = dppd_transaction_finalize(&transaction, &backends);
    if (rc != 0) {
        dppd_rule_observation_fault(&service->observation, rc);
        return isolate_control(service, rc);
    }
    return persist_current_repository(service);
}

record = find_record(repository, rule->id);
if (record != NULL) {
    /** equal 比较规则内容，不比较规则自身的 generation；相同内容重复提交不推进版本 */
    if (dppd_rule_equal(&record->rule, rule)) {
        result->status = DPPD_RULE_UNCHANGED;
        result->generation = record->rule.generation;
        return 0;
    }
    /**
     * 例：调用方读到 R1 版本 7，其他请求已将其改成版本 9
     * 本次携带 expected_generation = 7 且内容不同 → -ESTALE，拒绝覆盖版本 9
     * 比较的是 R1 当前版本，不是整个仓库的 generation；ANY 明确跳过此检查
     */
    if (expected_generation != DPPD_RULE_GENERATION_ANY && expected_generation != record->rule.generation)
        return -ESTALE;
    if (repository->generation >= UINT64_MAX - 1U)
        return -EOVERFLOW;
    record->rule = *rule;

    record->rule = *rule;
    /**
     * 新版本取仓库递增序列，不采用输入 rule->generation，也不是旧规则版本加 1
     * 例：仓库版本 12，R1 版本 7 → 用预期版本 7 更新成功 → 仓库和 R1 均变为 13
     * 其他规则保留各自的版本，更新已有记录不增加 count
     */
    record->rule.generation = ++repository->generation;
    result->status = DPPD_RULE_UPDATED;
    result->generation = record->rule.generation;
    return 0;
}

    uint32_t first = 0, last = index->count;
    while (first < last) {
        uint32_t middle = first + (last - first) / 2U;
        if (less(&index->keys[index->order[middle]], id, generation))
            first = middle + 1U;
        else
            last = middle;
    }
    return first;
}

uint32_t slot = index->free_head;
index->free_head = index->keys[slot].next_free;
index->keys[slot] = (struct dppd_slot_key){.id = id, .generation = generation};
/** 插入位置之后的编号整体右移一格，源和目标区域可能重叠，因此使用 memmove */
memmove(&index->order[position + 1U], &index->order[position],
    (size_t)(index->count - position) * sizeof(*index->order));
index->order[position] = slot;
++index->count;
*output = slot;
return 0;

    uint32_t position = lower_bound(index, id, generation);
    if (position == index->count)
        return -ENOENT;
    uint32_t slot = index->order[position];
    if (index->keys[slot].id != id || index->keys[slot].generation != generation)
        return -ENOENT;
    /** 左移删除位置之后的有效编号填补空位，重叠区域使用 memmove，完整对象不随之移动 */
    memmove(&index->order[position], &index->order[position + 1U],
        (size_t)(index->count - position - 1U) * sizeof(*index->order));
    /** 先接住原空闲链，再把刚释放的槽位设为链头，下一次插入可直接复用 */
    index->keys[slot] = (struct dppd_slot_key){.next_free = index->free_head};
    index->free_head = slot;
    --index->count;
    return 0;
}

int dppd_rule_repository_remove(struct dppd_rule_repository *repository, uint64_t rule_id, uint64_t expected_generation,
    bool *removed, uint64_t *generation)
{
    struct dppd_rule_record *record;

    if (repository == NULL || repository->records == NULL || rule_id == 0 || removed == NULL || generation == NULL)
        return -EINVAL;
    record = find_record(repository, rule_id);
    if (record == NULL) {
        if (expected_generation != DPPD_RULE_GENERATION_ANY && expected_generation != 0)
            return -ESTALE;
        *removed = false;
        *generation = repository->generation;
        return 0;
    }
    if (expected_generation != DPPD_RULE_GENERATION_ANY && expected_generation != record->rule.generation)
        return -ESTALE;

    /** 删除同样需要一个新的有效版本，不能先清空记录再发现版本号已耗尽 */
    if (repository->generation >= UINT64_MAX - 1U)
        return -EOVERFLOW;
    if (dppd_slot_index_erase(&repository->index, rule_id, 0) != 0)
        return -EUCLEAN;
    memset(record, 0, sizeof(*record));
    repository->count--;
    *removed = true;
    /* 删除同样推进 generation，避免重放旧版本时出现 ABA 问题 */
    *generation = ++repository->generation;
    return 0;
}

    rc = remove_actual_rule(service, rule_id, existing.generation);
    if (rc != 0)
        return rc;
    observe_stage(service, DPPD_RULE_STAGE_PUBLISH);
    rc = dppd_rule_repository_remove(&service->rules, rule_id, existing.generation, removed, generation);
    if (rc != 0 || !*removed) {
        dppd_rule_observation_fault(&service->observation, rc != 0 ? rc : -EUCLEAN);
        return isolate_control(service, rc != 0 ? rc : -EUCLEAN);
    }
    service->observation.applied = true;
    return persist_current_repository(service);
}

    next = snapshot_clone(active, backend->capacity);
    if (next == NULL) {
        (void)pthread_mutex_unlock(&backend->writer_lock);
        return -ENOMEM;
    }
    /** 只放弃副本持有的计数器引用，旧快照仍持有自己的引用，不能在此强行释放 */
    metrics_put(next->objects[index].metrics);
    memset(&next->objects[index], 0, sizeof(next->objects[index]));
    next->count--;
    int publish_error = publish_locked(backend, next);
    if (publish_error != 0) {
        snapshot_destroy(next, backend->capacity);
        (void)pthread_mutex_unlock(&backend->writer_lock);
        return publish_error;
    }
    (void)pthread_mutex_unlock(&backend->writer_lock);
    return 0;
}

        commit_was_attempted = i < commit_attempts;
        rc = backend->rollback(backend->context, item, item->backend_token, commit_was_attempted);
        if (rc == 0)
            item->state = DPPD_TRANSACTION_ITEM_ROLLED_BACK;
        /** 保留第一个清理错误，同时继续尝试清理其余条目，便于上层判断是否必须隔离 */
        else if (transaction->rollback_code == 0) {
            transaction->rollback_code = rc;
            transaction->rollback_item = i;
        }
    }
    transaction->state = transaction->rollback_code == 0 ? DPPD_TRANSACTION_ROLLED_BACK : DPPD_TRANSACTION_FAILED;
}

    if (pending->published)
        rc = dppd_software_backend_remove_version(backend, pending->rule.id, pending->rule.generation);
    free(pending);
    return rc;
}

        if (backend->finalize != NULL)
            backend->finalize(backend->context, item, item->backend_token);
        item->backend_token = 0;
    }
    transaction->state = DPPD_TRANSACTION_FINALIZED;
    return 0;
}

static void transaction_finalize(void *context, const struct dppd_transaction_item *item, uintptr_t token)
{
    (void)context;
    (void)item;
    free((struct dppd_software_pending_rule *)token);
}

    if (service->persistence_path == NULL)
        return 0;
    observe_stage(service, DPPD_RULE_STAGE_PERSIST);
    if (service->observation.context.rule_count > 1)
        observe_batch(service, DPPD_RULE_STAGE_PERSIST);
    rc = save_current_snapshot(service);
    if (rc != 0) {
        dppd_rule_observation_fault(&service->observation, rc);
        service->persistence_dirty = true;
        service->persistence_last_error = rc;
        return -EUCLEAN;
    }
    service->persistence_dirty = false;
    service->persistence_last_error = 0;
    service->persisted_generation = dppd_rule_repository_generation(&service->rules);
    service->observation.context = previous;
    return 0;
}

static int persistence_write_preflight(struct dppd_control_service *service)
{
    /**
     * clean 状态不重复保存，dirty 状态先修复上次未完成的保存
     * 修复失败就拒绝本次修改，这里不会通过丢弃内存中的规则来消除 dirty
     */
    return service->persistence_dirty ? persist_current_repository(service) : 0;
}
